import heapq

def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    adj = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    station_zones = [[] for _ in range(n)]
    for stop, z in stations:
        station_zones[stop].append(z)

    # State: (stop, mask of passes already bought)
    full = 1 << len(prices)
    INF = float("inf")
    dist = [[INF] * full for _ in range(n)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]  # (cost, stop, mask)

    while heap:
        d, u, mask = heapq.heappop(heap)
        if d > dist[u][mask]:
            continue
        if u == n - 1:
            return d

        # Buy a pass for a zone sold at this stop
        for z in station_zones[u]:
            bit = 1 << z
            if not mask & bit:
                nm = mask | bit
                nd = d + prices[z]
                if nd < dist[u][nm]:
                    dist[u][nm] = nd
                    heapq.heappush(heap, (nd, u, nm))

        # Ride an edge; free if its zone's pass is already owned
        for v, cost, zone in adj[u]:
            if zone != -1 and mask & (1 << zone):
                w = 0
            else:
                w = cost
            nd = d + w
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(heap, (nd, v, mask))

    return -1
